def find_prime_pairs(S):
    pairs = []
    # Since q < r, we iterate r from ceil(S/2) up to S-3 (since q >= 2)
    start_r = S // 2 + 1
    for r in range(start_r, S):
        if is_prime(r):
            q = S - r
            if is_prime(q):
                # We only need q < r, which is guaranteed by starting r > S/2
                pairs.append((q, r))
    return pairs

S = 800
prime_pairs = find_prime_pairs(S)

print(f"Total prime pairs (q, r) summing to 800: {len(prime_pairs)}")
print("Prime Pairs (q, r):")
for pair in prime_pairs:
    print(pair)

